/* empty css                                                                               */import{H as p}from"./chunks/HighLightText.D0qzB827.js";import{R as d}from"./chunks/ResourceCard.DSyPPpy0.js";import{c as i,o as r,a as s,b as t,d as e,e as a,w as l}from"./chunks/vitepress-theme-teek.VWKGyrHm.js";/* empty css                                                             *//* empty css                                                                            */const E=JSON.parse('{"title":"Embedding 与向量化：从 Token 到语义搜索","description":"从 Token Embedding 与 Sentence Embedding 的本质差异出发，详解专用嵌入模型的对比学习范式与主流模型选型，深入剖析语义搜索的向量相似度计算、ANN 近似检索算法及混合搜索策略，构建 Embedding 技术的完整知识体系。","frontmatter":{"title":"Embedding 与向量化：从 Token 到语义搜索","tldr":"Embedding 将离散符号映射为连续向量，使语义相近者在空间中靠近——它是语义搜索、RAG 检索与向量数据库的数学基石。","description":"从 Token Embedding 与 Sentence Embedding 的本质差异出发，详解专用嵌入模型的对比学习范式与主流模型选型，深入剖析语义搜索的向量相似度计算、ANN 近似检索算法及混合搜索策略，构建 Embedding 技术的完整知识体系。","tags":["概念","Embedding","Semantic-Search","RAG","ANN"],"categories":["大模型基础","核心概念"],"date":"2026-06-29T09:06:51.000Z","permalink":"/llm-basic/embedding-concept"},"headers":[],"relativePath":"llm-basic/embedding-concept.md","filePath":"22.大模型基础/02.核心概念/04.Embedding与向量化.md"}'),b={name:"llm-basic/embedding-concept.md"},N=Object.assign(b,{setup(o){return(c,n)=>(r(),i("div",null,[n[1]||(n[1]=s("h1",{id:"embedding-与向量化-从-token-到语义搜索",tabindex:"-1"},[a("Embedding 与向量化：从 Token 到语义搜索 "),s("a",{class:"header-anchor",href:"#embedding-与向量化-从-token-到语义搜索","aria-label":"Permalink to “Embedding 与向量化：从 Token 到语义搜索”"},"​")],-1)),n[2]||(n[2]=s("blockquote",null,[s("p",null,[s("strong",null,"摘要"),a(": Embedding（嵌入）是将离散符号映射至连续向量空间的核心技术，其「语义相近则向量相近」的基本性质使其成为语义搜索、RAG 检索与向量数据库的数学基石。本文首先严格区分了 Token Embedding（上下文无关的查表向量）与 Sentence Embedding（上下文感知的句级表示）两种易混淆的嵌入类型及其工程误区，随后系统对比了 LLM 自回归训练与专用 Embedding 模型对比学习范式之间的本质差异，并梳理了主流嵌入模型的选型参考。在应用层面，本文深入解析了语义搜索的三步流程、三种向量相似度度量、ANN 近似最近邻搜索的核心算法（HNSW、IVF、PQ）及其精度与速度权衡，以及混合搜索作为 RAG 系统最稳健检索方案的技术原理。")])],-1)),t(d,{resource:{name:"图集速览：Embedding、向量化与语义检索",description:"如果你对 Embedding 与向量化还比较陌生，建议先读这篇图集速览。用可视化图片集合和要点摘要，帮你快速理清从 Token 到语义搜索的向量世界。",url:"https://mp.weixin.qq.com/s/qqXghbHzZgubLs3zsOpIMQ",type:"article",tags:["Embedding","向量化","语义搜索","RAG"]}}),n[3]||(n[3]=e(`<h2 id="_1-embedding-嵌入-基本概念" tabindex="-1">1. Embedding（嵌入）基本概念 <a class="header-anchor" href="#_1-embedding-嵌入-基本概念" aria-label="Permalink to “1. Embedding（嵌入）基本概念”">​</a></h2><p><strong>Embedding（嵌入）</strong> 是将离散的符号（文字、图片、用户 ID）映射为连续向量空间中的点。其核心思想是：<strong>语义相近的东西，在向量空间中距离也近。</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>使用类比理解 Embedding：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>想象你有一张巨幅世界地图——</span></span>
<span class="line"><span></span></span>
<span class="line"><span>传统表示:   &quot;巴黎&quot; = 一个离散符号，计算机只知道这是字符串 &quot;巴黎&quot;</span></span>
<span class="line"><span>Embedding:  &quot;巴黎&quot; = [0.82, -0.31, 0.45, ..., 0.17]  (768 维向量)</span></span>
<span class="line"><span>            &quot;上海&quot; = [0.79, -0.28, 0.41, ..., 0.15]</span></span>
<span class="line"><span>            &quot;狗&quot;   = [-0.12, 0.88, -0.33, ..., -0.56]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>向量空间中：</span></span>
<span class="line"><span>  巴黎 vs 上海: cosine_sim ≈ 0.92 → 都是大城市！</span></span>
<span class="line"><span>  巴黎 vs 狗:   cosine_sim ≈ 0.03 → 完全无关</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="_1-1-token-embedding-vs-sentence-embedding" tabindex="-1">1.1 Token Embedding vs Sentence Embedding <a class="header-anchor" href="#_1-1-token-embedding-vs-sentence-embedding" aria-label="Permalink to “1.1 Token Embedding vs Sentence Embedding”">​</a></h3><p>两个关键维度区分：</p><p>这两种 Embedding 服务于完全不同的场景，核心区别在于：<strong>粒度不同、上下文感知不同、用途不同</strong>。</p><table tabindex="0"><thead><tr><th>维度</th><th>Token Embedding（词元嵌入）</th><th>Sentence Embedding（句嵌入）</th></tr></thead><tbody><tr><td><strong>粒度</strong></td><td>一个 Token → 一个向量</td><td><strong>一整句话/段落 → 一个向量</strong></td></tr><tr><td><strong>上下文感知</strong></td><td><strong>上下文无关</strong>：同一个「苹果」无论出现在科技新闻还是水果食谱，Embedding 层的向量都一样</td><td><strong>上下文相关</strong>：「苹果很好吃」和「苹果发布了新品」得到完全不同的整体向量</td></tr><tr><td><strong>上下文来源</strong></td><td>自身不带上下文，需通过后续 Attention 层融入</td><td><strong>向量本身已经编码了整个句子的语义</strong></td></tr><tr><td><strong>获取位置</strong></td><td>LLM 的第一层（Embedding 层），训练前就已存在</td><td>从模型中间层或专用模型提取，是计算后的结果</td></tr><tr><td><strong>典型维度</strong></td><td>768 ~ 12288（与模型 d_model 一致）</td><td>768 / 1024 / 4096（专用 Embedding 模型）</td></tr><tr><td><strong>主要用途</strong></td><td>LLM 内部表示——作为 Attention/FFN 的输入</td><td>语义搜索、文本聚类、相似度计算、RAG 检索</td></tr><tr><td><strong>典型模型</strong></td><td>GPT、LLaMA 的 Embedding 层</td><td>text-embedding-3、bge-large、GTE-Qwen2</td></tr></tbody></table><p><strong>Token Embedding 工作方式</strong>:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  &quot;苹果很好吃&quot; → Tokenizer → [&quot;苹果&quot;, &quot;很&quot;, &quot;好吃&quot;]</span></span>
<span class="line"><span>       │            │            │</span></span>
<span class="line"><span>       ▼            ▼            ▼</span></span>
<span class="line"><span>  查 Embedding 表，各自独立得到向量（此时三个向量互不感知）</span></span>
<span class="line"><span>       │            │            │</span></span>
<span class="line"><span>       └────────────┴────────────┘</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>                    ▼</span></span>
<span class="line"><span>          进入 Attention 层后才开始互相&quot;交流&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>Sentence Embedding 工作方式</strong>:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  &quot;苹果很好吃&quot; ──→ Embedding 模型 ──→ [0.15, 0.83, -0.42, ...]  ← 一个向量代表整句</span></span>
<span class="line"><span>  &quot;苹果发布了新品&quot; ──→ 同一模型 ──→ [0.72, -0.31, 0.58, ...]  ← 截然不同的向量</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  虽然都包含&quot;苹果&quot;，但两句的整体向量差异很大：</span></span>
<span class="line"><span>  cosine_sim(&quot;苹果很好吃&quot;, &quot;苹果发布了新品&quot;) ≈ 0.32  ← 语义完全不同</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="note custom-block github-alert"><p class="custom-block-title">为什么这个区分很重要？</p><p></p><p>很多人混淆这两者，导致实际工程中用错工具。常见误区：<strong>想用 LLM 的 Token Embedding 做语义搜索</strong>——但 Token Embedding 是上下文无关的，同一个「苹果」永远是同一个向量，无法区分「吃苹果」和「买苹果手机」。</p><p>正确的做法是用专门的 Sentence Embedding 模型（如 <code>text-embedding-3</code>、<code>bge-large</code>）来生成句子级向量。</p></div><p><strong>Embedding 维度与语义空间</strong></p>`,13)),t(p,{bold:""},{default:l(()=>[...n[0]||(n[0]=[a('Embedding 向量的维度（如 768、1024、4096）决定了语义空间的"分辨率"',-1)])]),_:1}),n[4]||(n[4]=e(`。类比理解如下：<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>维度太低（如 2 维）：</span></span>
<span class="line"><span>  只能表达&quot;正面-负面&quot;这一个维度，无法区分&quot;愤怒&quot;与&quot;悲伤&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>维度适中（如 768 维）：</span></span>
<span class="line"><span>  可以同时表达&quot;情绪&quot;&quot;主题&quot;&quot;风格&quot;&quot;语言&quot;&quot;正式度&quot;等数十个语义维度</span></span>
<span class="line"><span></span></span>
<span class="line"><span>维度太高（如 4096 维）：</span></span>
<span class="line"><span>  表达力更强，但存储和计算成本更大；向量检索时维度灾难现象加剧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>常见模型的 Embedding 维度：OpenAI text-embedding-3-small（512/1536 可选）、BGE-M3（1024）、GTE-Qwen2-7B（3584）。</p><h2 id="_2-embedding-model" tabindex="-1">2. Embedding Model <a class="header-anchor" href="#_2-embedding-model" aria-label="Permalink to “2. Embedding Model”">​</a></h2><p>Embedding 不是&quot;大模型顺手做的事&quot;——有专门的<strong>嵌入模型（Embedding Model）</strong>针对&quot;把文本变成好向量&quot;这个目标做专门训练。</p><p><strong>LLM vs 专用 Embedding Model 的本质差异：</strong></p><table tabindex="0"><thead><tr><th></th><th>LLM（如 GPT-4）</th><th>专用 Embedding Model</th></tr></thead><tbody><tr><td><strong>目标</strong></td><td>预测下一个 token（生成）</td><td>让相似文本的向量近，不相似文本的向量远（对比学习）</td></tr><tr><td><strong>输出</strong></td><td>概率分布（词表大小）</td><td>固定长度向量（如 1536 维）</td></tr><tr><td><strong>训练范式</strong></td><td>自回归（Next-Token Prediction）</td><td>对比学习（Contrastive Learning）</td></tr><tr><td><strong>架构</strong></td><td>Decoder-Only Transformer</td><td><strong>Encoder-Only 或 Decoder 池化</strong></td></tr><tr><td><strong>典型任务</strong></td><td>聊天、写作、编程</td><td><strong>搜索、聚类、分类、RAG 检索</strong></td></tr></tbody></table><p><strong>主流专用 Embedding Model 一览：</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>维度</th><th>多语言</th><th>特点</th></tr></thead><tbody><tr><td>OpenAI text-embedding-3-small</td><td>512/1536</td><td>多语言</td><td>API 调用，无需部署</td></tr><tr><td>OpenAI text-embedding-3-large</td><td>256/1024/3072</td><td>多语言</td><td>更强，更贵</td></tr><tr><td>BGE-M3（BAAI）</td><td>1024</td><td>中英为主</td><td>开源 SOTA，支持稠密+稀疏混合检索</td></tr><tr><td>GTE-Qwen2-7B（阿里）</td><td>3584</td><td>多语言</td><td>基于 Qwen2，中文表现顶尖</td></tr><tr><td>Jina Embeddings v3</td><td>1024</td><td>多语言</td><td>支持任务特定 LoRA adapters</td></tr><tr><td>Cohere Embed v3</td><td>1024</td><td>多语言</td><td>压缩表示，适合大规模检索</td></tr><tr><td>Nomic Embed Text</td><td>768/1376</td><td>英文</td><td>全开源（数据+代码+权重）</td></tr></tbody></table><p><strong>通用 LLM 做 Embedding：可行但&quot;大材小用&quot;。</strong> 你可以取 LLM 最后一层隐状态的均值作为文本 Embedding，但专用模型用更少的参数达到更好效果——7B 参数的 GTE-Qwen2 在 MTEB 检索基准上超越了多数通用 LLM。</p><h2 id="_3-语义搜索-semantic-search" tabindex="-1">3. 语义搜索（Semantic Search） <a class="header-anchor" href="#_3-语义搜索-semantic-search" aria-label="Permalink to “3. 语义搜索（Semantic Search）”">​</a></h2><h3 id="_3-1-语义搜索的完整流程" tabindex="-1">3.1 语义搜索的完整流程 <a class="header-anchor" href="#_3-1-语义搜索的完整流程" aria-label="Permalink to “3.1 语义搜索的完整流程”">​</a></h3><p><strong>语义搜索（Semantic Search）</strong> 是基于向量相似度匹配的搜索方式，核心流程只有三步：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>语义搜索的完整流程：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌─────────────┐     ┌──────────────┐     ┌──────────────┐</span></span>
<span class="line"><span>│  1. 向量化    │     │  2. 相似计算   │     │  3. 结果排序   │</span></span>
<span class="line"><span>│              │     │              │     │              │</span></span>
<span class="line"><span>│ 查询: &quot;怎么   │     │ cos(查询, 文档1) │    │ 文档3: 0.92  │</span></span>
<span class="line"><span>│  部署模型?&quot;  │ →   │ cos(查询, 文档2) │ →  │ 文档1: 0.87  │</span></span>
<span class="line"><span>│   ↓          │     │ cos(查询, 文档3) │    │ 文档2: 0.34  │</span></span>
<span class="line"><span>│ [0.1, -0.3]  │     │ ...            │     │ ...          │</span></span>
<span class="line"><span>│              │     │              │     │              │</span></span>
<span class="line"><span>│ 文档库:      │     │              │     │              │</span></span>
<span class="line"><span>│  文档1 → [..]│     │              │     │              │</span></span>
<span class="line"><span>│  文档2 → [..]│     │              │     │              │</span></span>
<span class="line"><span>│  文档3 → [..]│     │              │     │              │</span></span>
<span class="line"><span>└─────────────┘     └──────────────┘     └──────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p><strong>三种向量相似度度量对比：</strong></p><table tabindex="0"><thead><tr><th>度量方式</th><th>公式</th><th>值域</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>余弦相似度</strong></td><td>(A·B) / (</td><td>A</td><td>·</td></tr><tr><td><strong>欧氏距离</strong></td><td>sqrt(Σ(Aᵢ-Bᵢ)²)</td><td>[0, ∞)</td><td>关心绝对距离（长度+方向）</td></tr><tr><td><strong>点积</strong></td><td>A·B = Σ AᵢBᵢ</td><td>(-∞, ∞)</td><td>向量已归一化时等价于余弦相似度</td></tr></tbody></table><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>余弦相似度的几何直觉（二维示意）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>         查询向量 Q</span></span>
<span class="line"><span>           ↗</span></span>
<span class="line"><span>          /  夹角 ≈ 15°</span></span>
<span class="line"><span>         /</span></span>
<span class="line"><span>        * 文档向量 D₁（相关）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>             查询向量 Q</span></span>
<span class="line"><span>               ↗</span></span>
<span class="line"><span>              /</span></span>
<span class="line"><span>             /</span></span>
<span class="line"><span>        ←──→ 夹角 ≈ 130°</span></span>
<span class="line"><span>        *</span></span>
<span class="line"><span>    文档向量 D₂（不相关）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cos(15°) ≈ 0.97 → 高度相关！</span></span>
<span class="line"><span>cos(130°) ≈ -0.64 → 几乎无关</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p><strong>ANN（Approximate Nearest Neighbor，近似最近邻搜索）：</strong> 当文档库达到百万甚至亿级时，逐个计算余弦相似度不可行。ANN 算法（如 HNSW、IVF、PQ）通过牺牲一点精度换取巨大速度提升——检索 1 亿条向量从&quot;几分钟&quot;变成&quot;几毫秒&quot;。主流向量数据库（Milvus、Qdrant、Pinecone）在内部都使用了 ANN 索引。</p><h3 id="_3-2-ann-approximate-nearest-neighbor-近似最近邻搜索" tabindex="-1">3.2 ANN （Approximate Nearest Neighbor，近似最近邻搜索） <a class="header-anchor" href="#_3-2-ann-approximate-nearest-neighbor-近似最近邻搜索" aria-label="Permalink to “3.2 ANN （Approximate Nearest Neighbor，近似最近邻搜索）”">​</a></h3><p>ANN 是一种在百万甚至亿级向量中快速找到与查询向量最相似的 Top-K 个向量的算法。它的核心取舍是：<strong>用少量精度换取数量级的搜索速度提升</strong>。</p><div class="tip custom-block"><p class="custom-block-title">为什么需要 ANN？</p><p>暴力搜索（逐一对比所有向量）在数据量小时完全可行，但向量数据库的规模往往是百万到十亿级：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>暴力搜索（Brute Force）：</span></span>
<span class="line"><span>   1 亿条向量 × 768 维浮点数 × 两次浮点运算 = 每秒约 5000 次比对</span></span>
<span class="line"><span>   → 检索一次需要 20000 秒 ≈ 5.5 小时 ❌</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ANN 索引：</span></span>
<span class="line"><span>   先在索引中快速定位候选区域（几毫秒），再对候选集做精确比对（几毫秒）</span></span>
<span class="line"><span>   → 检索一次只需 1~10 毫秒 ✅</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div></div><p><strong>ANN 的基本原理——用索引代替全量对比：</strong></p><p>ANN 的核心思路是在<strong>建库时</strong>花时间构建索引结构，把相似向量预组织在一起；<strong>查询时</strong>用索引快速缩小搜索范围，只在小范围内做精确计算：</p><table tabindex="0"><thead><tr><th>阶段</th><th>操作</th><th>耗时</th></tr></thead><tbody><tr><td><strong>建库（离线）</strong></td><td>对所有向量建索引，相当于给整个向量空间画一张「地图」</td><td>数分钟到数小时（只做一次）</td></tr><tr><td><strong>查询（在线）</strong></td><td>根据查询向量在索引中定位候选区域，只计算候选区域内的向量</td><td>1~10 毫秒</td></tr></tbody></table><p><strong>主流 ANN 算法：</strong></p><table tabindex="0"><thead><tr><th>算法</th><th>原理</th><th>特点</th></tr></thead><tbody><tr><td><strong>HNSW（分层可导航小世界图）</strong></td><td>构建多层图结构，上层做「高速公路」快速跳到目标区域，下层做精确查找</td><td>当前综合性能最强，查询快、召回率高，但内存开销较大</td></tr><tr><td><strong>IVF（倒排文件索引）</strong></td><td>用 K-Means 把所有向量聚成 N 个簇，查询时只在最近几个簇内搜索</td><td>简单高效，内存友好，适合大规模数据</td></tr><tr><td><strong>PQ（乘积量化）</strong></td><td>将高维向量切分成多段，每段独立做量化压缩，用近似距离代替精确距离</td><td>内存极度节省，但召回率略低，常与 IVF 组合使用</td></tr><tr><td><strong>IVF-PQ</strong></td><td>IVF 做粗定位 + PQ 做压缩存储</td><td>工业界最常用的组合，兼顾速度与内存</td></tr><tr><td><strong>DiskANN</strong></td><td>将索引存在 SSD 上，只按需加载需要的部分到内存</td><td>超大规模（十亿级）、内存有限时的首选</td></tr></tbody></table><p><strong>HNSW 直观理解</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> </span></span>
<span class="line"><span>   层级 2（稀疏，长距离跳跃）：</span></span>
<span class="line"><span>     ● ──────────── ●</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>   层级 1（中等密度）：</span></span>
<span class="line"><span>     ● ───● ───● ───●</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>   层级 0（最密，精确搜索）：</span></span>
<span class="line"><span>     ●─●─●─●─●─●─●─●</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>   查询路径：从顶层快速跳到目标区域 → 逐层下降 → 底层精确比对 → 返回结果</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><strong>精度 vs 速度的权衡：</strong></p><p>ANN 索引通常有一个可调节的参数来控制这个权衡。以 HNSW 为例，<code>ef_search</code> 越大（搜索时探索更多候选），召回率越高但越慢：</p><table tabindex="0"><thead><tr><th>配置</th><th>召回率</th><th>查询延迟</th><th>适用场景</th></tr></thead><tbody><tr><td>ef_search=16</td><td>~90%</td><td>~1ms</td><td>对延迟敏感的在线服务</td></tr><tr><td>ef_search=64</td><td>~97%</td><td>~3ms</td><td>一般推荐场景</td></tr><tr><td>ef_search=256</td><td>~99.5%</td><td>~10ms</td><td>对精度要求极高的场景</td></tr></tbody></table><p><strong>主流向量数据库的 ANN 实现：</strong></p><table tabindex="0"><thead><tr><th>向量数据库</th><th>ANN 算法</th><th>特点</th></tr></thead><tbody><tr><td><strong>Milvus</strong></td><td>HNSW, IVF-PQ, DiskANN</td><td>功能最全，支持十亿级向量</td></tr><tr><td><strong>Qdrant</strong></td><td>HNSW</td><td>Rust 实现，性能优异，API 友好</td></tr><tr><td><strong>Pinecone</strong></td><td>自研（不公开）</td><td>全托管，零运维，按量付费</td></tr><tr><td><strong>Weaviate</strong></td><td>HNSW, Flat</td><td>自带向量化模块</td></tr><tr><td><strong>Chroma</strong></td><td>HNSW</td><td>轻量级，适合原型开发</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么语义搜索是 RAG 的基石？</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>传统关键词搜索：          语义搜索（向量搜索）：</span></span>
<span class="line"><span>用户: &quot;怎么保持健康？&quot;    用户: &quot;怎么保持健康？&quot;</span></span>
<span class="line"><span>  ↓                         ↓</span></span>
<span class="line"><span>匹配&quot;保持&quot;&quot;健康&quot;           向量化 query</span></span>
<span class="line"><span>  ↓                         ↓</span></span>
<span class="line"><span>找到含这些词的文档          找到向量最接近的文档</span></span>
<span class="line"><span>  ↓                         ↓</span></span>
<span class="line"><span>❌ 漏掉 &quot;养生秘诀&quot;         ✅ &quot;养生秘诀&quot; 高相似度！（语义匹配）</span></span>
<span class="line"><span>❌ 漏掉 &quot;锻炼身体&quot;         ✅ &quot;锻炼身体&quot; 也高相似度</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>这就是为什么 RAG 系统中，检索通常使用<strong>混合搜索（Hybrid Search）</strong>：BM25 关键词匹配 + 向量语义匹配，再通过 Reranker 做最后排序，是最稳健的方案。</p></div>`,34))]))}});export{E as __pageData,N as default};
